INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerkmodell immer sieben Ebenen hat?', 2, '[{"text": "Ja", "correct": true, "because": "Standard mit 7 Schichten"}, {"text": "Nein", "correct": false, "because": "Festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebene ist für die physische Verbindung zuständig?', 3, '[{"text": "Schicht 1", "correct": true, "because": "Bitübertragung"}, {"text": "Schicht 3", "correct": false, "because": "Routing"}, {"text": "Schicht 7", "correct": false, "because": "Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernehmen die verschiedenen Ebenen?', 5, '[{"text": "Physische Übertragung", "correct": true, "because": "Schicht 1"}, {"text": "Routing", "correct": true, "because": "Schicht 3"}, {"text": "Datenformatierung", "correct": true, "because": "Schicht 6"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schicht 2 sichert Datenverbindungen. b) Schicht 4 verwaltet Sitzungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 4 ist Transport"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerkkommunikation plane?', 4, '[{"text": "Physische Schicht", "correct": false, "because": "Übertragung nötig"}, {"text": "Transportschicht", "correct": false, "because": "Datenfluss"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Ebene für alle Aufgaben reicht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Aufgaben verteilt"}, {"text": "Ja", "correct": false, "because": "Sieben Ebenen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schicht übernimmt die Datenverbindung zwischen zwei Geräten?', 3, '[{"text": "Schicht 2", "correct": true, "because": "Datenlink-Schicht"}, {"text": "Schicht 1", "correct": false, "because": "Nur physisch"}, {"text": "Schicht 5", "correct": false, "because": "Sitzungssteuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Schichtenmodell?', 5, '[{"text": "Modularität", "correct": true, "because": "Getrennte Funktionen"}, {"text": "Fehlerisolierung", "correct": true, "because": "Schichtweise Analyse"}, {"text": "Standardisierung", "correct": true, "because": "Einheitliche Protokolle"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Schicht 3 für Routing ist und b) Schicht 7 nur für Hardware. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 7 ist Anwendung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerkschichten zu verstehen?', 4, '[{"text": "Schichtfunktionen", "correct": false, "because": "Definieren Aufgaben"}, {"text": "Protokolle", "correct": false, "because": "Regeln Kommunikation"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Schicht 4 für Routing zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 3 macht Routing"}, {"text": "Ja", "correct": false, "because": "Schicht 4 ist Transport"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schichten sind für die Datenübertragung wichtig?', 4, '[{"text": "Schicht 1", "correct": true, "because": "Physische Übertragung"}, {"text": "Schicht 4", "correct": true, "because": "Transportsteuerung"}, {"text": "Schicht 7", "correct": false, "because": "Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schicht 7 die physische Verbindung managed. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 1 tut das"}, {"text": "Ja", "correct": false, "because": "Schicht 7 ist Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Schichtenmodell?', 3, '[{"text": "Strukturierte Kommunikation", "correct": true, "because": "Klarer Ablauf"}, {"text": "Datenkompression", "correct": false, "because": "Sekundär"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schicht 5 managed Sitzungen. b) Schicht 2 ist für IP-Adressen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 2 ist MAC"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Schicht 3?', 4, '[{"text": "Routing", "correct": true, "because": "Leitet Daten zwischen Netzen"}, {"text": "Physische Verbindung", "correct": false, "because": "Schicht 1"}, {"text": "Anwendungslogik", "correct": false, "because": "Schicht 7"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schicht 6 Datenformate managed?', 2, '[{"text": "Ja", "correct": true, "because": "Darstellungsschicht"}, {"text": "Nein", "correct": false, "because": "Falsche Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Schichtenmodell nützlich?', 5, '[{"text": "Aufgabentrennung", "correct": true, "because": "Modularität"}, {"text": "Standardisierung", "correct": true, "because": "Protokolle einheitlich"}, {"text": "Fehlerisolierung", "correct": true, "because": "Schichtweise Prüfung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Schicht 1 für Datenformate zuständig?', 3, '[{"text": "Nein", "correct": true, "because": "Schicht 6 macht das"}, {"text": "Ja", "correct": false, "because": "Schicht 1 ist physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Schicht 4?', 4, '[{"text": "TCP-Verbindung aufbauen", "correct": true, "because": "Transportprotokoll"}, {"text": "Kabel anschließen", "correct": false, "because": "Schicht 1"}, {"text": "Webseite anzeigen", "correct": false, "because": "Schicht 7"}]');
